CREATE TABLE public.fleet_monitor_roles (user_id uuid PRIMARY KEY, role text NOT NULL DEFAULT 'admin' CHECK (role IN ('admin','reviewer','viewer')));
GRANT SELECT ON public.fleet_monitor_roles TO authenticated;
GRANT ALL ON public.fleet_monitor_roles TO service_role;
ALTER TABLE public.fleet_monitor_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY fleet_role_read ON public.fleet_monitor_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.fleet_monitor_workspaces (user_id uuid PRIMARY KEY DEFAULT auth.uid(), payload jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.fleet_monitor_workspaces TO authenticated;
GRANT ALL ON public.fleet_monitor_workspaces TO service_role;
ALTER TABLE public.fleet_monitor_workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY fleet_workspace_read ON public.fleet_monitor_workspaces FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY fleet_workspace_edit ON public.fleet_monitor_workspaces FOR UPDATE TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.fleet_monitor_roles r WHERE r.user_id = auth.uid() AND r.role = 'admin')) WITH CHECK (user_id = auth.uid() AND octet_length(payload::text) < 2000000);
CREATE TABLE public.fleet_monitor_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), alert_key text NOT NULL CHECK (length(alert_key) BETWEEN 1 AND 250), reviewer_name text NOT NULL CHECK (length(trim(reviewer_name)) BETWEEN 1 AND 200), decision text NOT NULL CHECK (decision IN ('confirmed','dismissed','action_taken')), note text NOT NULL CHECK (length(trim(note)) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.fleet_monitor_reviews TO authenticated;
GRANT ALL ON public.fleet_monitor_reviews TO service_role;
ALTER TABLE public.fleet_monitor_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY fleet_reviews_read ON public.fleet_monitor_reviews FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY fleet_reviews_write ON public.fleet_monitor_reviews FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.fleet_monitor_roles r WHERE r.user_id = auth.uid() AND r.role IN ('admin','reviewer')));
CREATE FUNCTION public.initialize_fleet_monitor() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; INSERT INTO public.fleet_monitor_roles(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; INSERT INTO public.fleet_monitor_workspaces(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.initialize_fleet_monitor() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.initialize_fleet_monitor() TO authenticated;
CREATE TABLE public.fleet_monitor_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, action text NOT NULL, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.fleet_monitor_audit TO authenticated;
GRANT ALL ON public.fleet_monitor_audit TO service_role;
ALTER TABLE public.fleet_monitor_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY fleet_audit_read ON public.fleet_monitor_audit FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.audit_fleet_workspace() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.fleet_monitor_audit(user_id, action, before_value, after_value) VALUES(NEW.user_id, TG_TABLE_NAME, to_jsonb(OLD), to_jsonb(NEW)); RETURN NEW; END; $$;
CREATE TRIGGER fleet_workspace_audit AFTER UPDATE ON public.fleet_monitor_workspaces FOR EACH ROW EXECUTE FUNCTION public.audit_fleet_workspace();
CREATE TRIGGER fleet_review_audit AFTER INSERT ON public.fleet_monitor_reviews FOR EACH ROW EXECUTE FUNCTION public.audit_fleet_workspace();